INSERT INTO `attraction_reviews` VALUES (34,'2026-06-25 16:31:51.776679','2026-06-25 16:31:51.776679','일출이 정말 장관이었어요! 새벽에 올라간 보람이 있네요.','126508001',5,37),(35,'2026-06-25 16:31:51.786330','2026-06-25 16:31:51.786330','한복 입고 입장하면 무료라 더 좋았어요.','126508',4,39),(36,'2026-06-25 16:31:51.792473','2026-06-25 16:31:51.792473','백사장이 넓고 야경이 환상적입니다.','126508003',5,38),(37,'2026-06-25 16:31:51.799103','2026-06-25 16:31:51.799103','물이 맑고 가족 단위로 오기 좋아요.','126508002',4,40),(38,'2026-06-25 16:31:51.804640','2026-06-25 16:31:51.804640','야경 보러 갔는데 케이블카도 재밌어요.','126461',5,41),(39,'2026-06-25 16:31:51.809068','2026-06-25 16:31:51.809068','여름엔 사람 많지만 그만한 이유가 있네요.','126508003',4,42),(40,'2026-06-25 16:31:51.814233','2026-06-25 16:31:51.814233','고즈넉한 분위기가 정말 좋았습니다.','126508',5,43),(41,'2026-06-25 16:31:51.819156','2026-06-25 16:31:51.819156','경치가 멋지고 둘레길도 잘 돼 있어요.','126508001',4,44);
/*!40000 ALTER TABLE `attraction_reviews` ENABLE KEYS */;
UNLOCK TABLES;
