INSERT INTO `hot_places` VALUES (33,'2026-06-25 16:31:52.826991','2026-06-25 16:31:52.853615','부산광역시 영도구 흰여울길','ATTRACTION','영도 절벽 위에 옹기종기 들어선 달동네가 시간을 거슬러 올라간 느낌을 줘요. 좁은 골목마다 바다 뷰가 숨어 있고, 영화 촬영지로 알려지면서 부산 힙스터들의 단골 나들이 코스가 됐어요.',35.0789,129.0468,'흰여울문화마을','APPROVED',38,1248,4.8,508),(34,'2026-06-25 16:31:52.873608','2026-06-25 16:31:52.888867','제주특별자치도 서귀포시 성산읍 일출로','NATURE','분화구를 향해 오르는 계단길에서 바라보는 제주 동쪽 바다가 시원하게 펼쳐져요. 유네스코 세계자연유산으로 지정된 곳으로, 이른 새벽 일출 시간에 맞춰 오르는 게 진짜 묘미예요.',33.4581,126.9425,'성산일출봉','APPROVED',37,1087,4.6,421),(35,'2026-06-25 16:31:52.904402','2026-06-25 16:31:52.921584','서울특별시 종로구 계동길','ATTRACTION','600년 넘은 한옥들이 좁다란 골목을 따라 이어져 조선 시대 속으로 걸어 들어가는 기분이 들어요. 이른 아침에 오면 인파 없이 고즈넉한 분위기를 온전히 즐길 수 있어요.',37.5826,126.9831,'북촌한옥마을','APPROVED',39,876,4.5,409),(36,'2026-06-25 16:31:52.939881','2026-06-25 16:31:52.952152','제주특별자치도 제주시 한림읍 협재리','NATURE','수심이 얕아 걷다 보면 발밑으로 에메랄드빛 바닥이 훤히 들여다보여요. 물빛이 워낙 맑아서 날씨가 흐려도 빛깔이 살아 있고, 멀리 비양도가 수평선에 떠 있어 사진 찍기에도 좋아요.',33.394,126.2396,'협재해수욕장','APPROVED',37,765,4.4,395),(37,'2026-06-25 16:31:52.964967','2026-06-25 16:31:52.979345','부산광역시 사하구 감내2로','ATTRACTION','가파른 산비탈을 따라 형형색색의 집들이 계단처럼 쌓여 있는 독특한 경관이에요. 골목 곳곳에 숨어 있는 벽화와 조형물을 찾아다니는 재미가 쏠쏠한 부산의 예술 마을이에요.',35.0975,129.0107,'감천문화마을','APPROVED',38,646,4.3,390),(38,'2026-06-25 16:31:52.988560','2026-06-25 16:31:53.002208','서울특별시 종로구 창경궁로','RESTAURANT','100년 넘은 재래시장 안에 이름난 먹거리 노점들이 가득 들어차 있어요. 바삭한 빈대떡과 꼬들꼬들한 마약김밥은 한 번 먹으면 두고두고 생각나는 맛이에요.',37.5701,126.9999,'광장시장 먹자골목','APPROVED',40,526,4.3,322),(39,'2026-06-25 16:31:53.013054','2026-06-25 16:31:53.024776','서울특별시 용산구 남산공원길','ATTRACTION','케이블카를 타고 오르면 서울 도심이 360도 파노라마로 한눈에 들어와요. 해 질 녘부터 야경이 피어오르는 순간이 특히 아름다워서 데이트 코스로도 인기가 높아요.',37.5512,126.9882,'남산서울타워','APPROVED',39,414,4.2,226),(40,'2026-06-25 16:31:53.033156','2026-06-25 16:31:53.046236','제주특별자치도 서귀포시 안덕면 신화역사로','CAFE','제주 안덕 들판에 펼쳐진 초록빛 녹차밭이 카페 창문 너머로 이어져요. 녹차 아이스크림과 함께 차 한 잔 마시며 천천히 쉬어 가기 좋은 힐링 공간이에요.',33.3056,126.2895,'오설록 티 뮤지엄','APPROVED',37,284,4.1,101);
