INSERT INTO `notices` VALUES (1,'2026-06-22 09:25:51.881016','2026-06-22 09:25:51.881016','필독','관통 여행 서비스가 베타로 오픈했습니다. 이용 중 불편한 점은 언제든 알려 주세요. 감사합니다.',_binary '','서비스 베타 오픈 안내'),(2,'2026-06-22 09:25:51.942754','2026-06-22 09:25:51.942754','안내','탐색 화면의 지도가 카카오 지도로 전환되었습니다. 현재 위치 기반 주변 관광지 정렬을 지원해요.',_binary '\0','카카오 지도 연동 안내'),(3,'2026-06-22 09:25:51.968531','2026-06-22 09:25:51.968531','업데이트','이제 동행인·예산·테마를 입력하면 더 정교한 일정을 추천해 드려요. 마이페이지 > AI 여행에서 사용해 보세요.',_binary '\0','AI 일정 생성 기능이 개선되었어요');
