INSERT INTO `posts` VALUES (65,'2026-06-25 16:31:51.929395','2026-06-25 16:31:51.950533','REVIEW','렌터카 없이 버스와 도보로만 2박 3일을 다녀봤어요. 처음엔 불편할까 걱정했는데 동선만 잘 짜면 충분히 다닐 만하더라고요. 제가 실제로 다닌 코스와 버스 노선까지 아래에 정리해뒀으니 참고하세요.',_binary '\0',72,'혼자 제주 2박3일 뚜벅이 후기',0,37),(66,'2026-06-25 16:31:52.001263','2026-06-25 16:31:52.010286','REVIEW','해운대에서 시작해 광안리까지 해안을 따라 천천히 걸었어요. 주말이라 사람이 정말 많았지만 그만큼 활기차서 좋았습니다. 야경 포인트마다 사진 찍느라 시간 가는 줄 몰랐네요.',_binary '\0',54,'부산 1박2일 다녀온 솔직 후기',0,38),(67,'2026-06-25 16:31:52.040701','2026-06-25 16:31:52.050197','REVIEW','안목해변 커피거리에서 파도 소리를 들으며 커피를 마셨는데 그 자체로 힐링이었어요. 바다 바로 앞 카페에 자리 잡고 한참을 멍하니 앉아 있었네요.',_binary '\0',48,'강릉 바다 보러 다녀왔어요',0,41),(68,'2026-06-25 16:31:52.075255','2026-06-25 16:31:52.150512','REVIEW','불국사와 첨성대를 거쳐 황리단길까지 알차게 둘러봤어요. 낮에는 유적지, 밤에는 동궁과 월지 야경으로 하루가 꽉 찼습니다. 생각보다 야경 명소가 많아서 놀랐네요.',_binary '\0',63,'경주 역사 여행 2박3일 후기',0,43),(69,'2026-06-25 16:31:52.184675','2026-06-25 16:31:52.192665','REVIEW','케이블카를 타고 내려다본 여수 밤바다는 정말 잊을 수가 없어요. 노래 가사가 괜히 나온 게 아니라는 걸 직접 보고서야 알았네요. 해상 케이블카는 꼭 타보시길 추천해요.',_binary '\0',58,'여수 밤바다 보고 온 후기',0,42),(70,'2026-06-25 16:31:52.219761','2026-06-25 16:31:52.228865','QUESTION','이번 주말에 부산으로 1박 2일 여행을 가요. 야경을 정말 좋아하는데 어디가 제일 예쁜지 추천 부탁드려요 🙏 도보나 대중교통으로 갈 수 있으면 더 좋아요.',_binary '\0',41,'부산 야경 명소 어디가 제일 좋나요?',0,38),(71,'2026-06-25 16:31:52.259532','2026-06-25 16:31:52.271518','QUESTION','차가 없어서 대중교통으로만 다녀와야 해요. 서울 근교로 당일치기 다녀오기 좋은 곳 추천해주세요. 너무 빡센 코스 말고 여유롭게 쉬다 올 수 있으면 좋겠어요.',_binary '\0',38,'서울 근교 당일치기 어디가 좋을까요?',0,39),(72,'2026-06-25 16:31:52.390419','2026-06-25 16:31:52.399406','QUESTION','속초로 여행 가는데 닭강정 말고 현지인이 가는 맛집이 궁금해요. 회 종류 말고도 추천해주실 만한 메뉴 있을까요? 아침 식사로 든든하게 먹을 곳도 찾고 있어요.',_binary '\0',45,'속초 맛집 추천 부탁드려요',0,44),(73,'2026-06-25 16:31:52.419312','2026-06-25 16:31:52.428048','QUESTION','운전이 서툰 편이라 제주에서 렌터카를 빌려야 할지 고민이에요. 렌터카 없이 대중교통으로만 다니면 많이 불편할까요? 두 방법 다 경험해보신 분들 의견이 궁금합니다.',_binary '\0',67,'제주 렌터카 vs 뚜벅이 고민돼요',0,37),(74,'2026-06-25 16:31:52.454082','2026-06-25 16:31:52.464459','QUESTION','바다가 보이는 숙소 위주로 찾고 있어요. 1박 10만원 정도 예산인데 가성비 좋은 곳 추천 부탁드려요. 조용히 쉴 수 있는 분위기면 더 좋겠습니다.',_binary '\0',52,'강릉 숙소 어디가 좋나요?',0,41),(75,'2026-06-25 16:31:52.489456','2026-06-25 16:31:52.499694','TIP','경복궁 야간개장은 예매 경쟁이 치열해서 오픈 시간에 바로 들어가야 해요. 예매 꿀팁과 추천 동선을 아래에 정리해뒀습니다. 한복을 입으면 입장료가 무료라는 점도 잊지 마세요.',_binary '\0',80,'서울 고궁 야간개장 일정 공유합니다',0,39),(76,'2026-06-25 16:31:52.523551','2026-06-25 16:31:52.533936','TIP','특가 알림을 설정해두고 새벽 시간대 항공권을 노리면 반값에도 잡을 수 있어요. 평일 출발·복귀로 잡는 게 가장 저렴한 핵심 포인트입니다. 성수기는 두 달 전부터 미리 예매하는 걸 추천해요.',_binary '\0',85,'제주 항공권 싸게 사는 꿀팁',0,37),(77,'2026-06-25 16:31:52.566363','2026-06-25 16:31:52.575481','TIP','충전기, 상비약, 보조배터리처럼 빠뜨리기 쉬운 것부터 먼저 챙기세요. 품목별로 파우치를 나눠 담으면 가방 안에서 찾기도 편하고 짐도 줄어들어요.',_binary '\0',61,'여행 짐 싸기 체크리스트 공유',0,40),(78,'2026-06-25 16:31:52.599256','2026-06-25 16:31:52.609595','TIP','해운대, 광안리, 자갈치시장까지 주요 명소는 대부분 지하철로 닿아요. 하루에 여러 곳을 도는 일정이면 1일권을 끊는 게 훨씬 저렴합니다. 환승 동선까지 아래에 정리해뒀어요.',_binary '\0',49,'부산 지하철로 여행하는 법',0,38),(79,'2026-06-25 16:31:52.627412','2026-06-25 16:31:52.633825','TIP','황리단길 근처에서 한복을 빌리면 반납도 편하고 사진 찍을 명소도 바로 가까워요. 평일에 가면 한산해서 인생샷 건지기에도 훨씬 좋습니다. 대여점마다 소품 종류가 다르니 미리 비교해보세요.',_binary '\0',57,'경주 한복 대여 꿀팁',0,43),(80,'2026-06-25 16:31:52.655928','2026-06-25 16:31:52.663836','RESTAURANT','현지인 추천을 받아 다녀온 제주 흑돼지 맛집 다섯 곳을 정리했어요. 연탄에 구운 흑돼지는 겉은 바삭하고 속은 촉촉해서 정말 별미였습니다. 가게별 특징과 추천 메뉴도 함께 적어뒀어요.',_binary '\0',84,'제주 흑돼지 맛집 BEST 5 🐷',0,40),(81,'2026-06-25 16:31:52.690664','2026-06-25 16:31:52.700295','RESTAURANT','서면과 남포동 일대 돼지국밥집 다섯 곳을 직접 다니며 비교해봤어요. 집집마다 국물 진하기와 고기 양이 달라서 취향대로 고르시면 됩니다. 부추를 듬뿍 넣어 드시는 걸 추천해요.',_binary '\0',66,'부산 돼지국밥 맛집 정리',0,38),(82,'2026-06-25 16:31:52.724372','2026-06-25 16:31:52.732102','RESTAURANT','광장시장은 빈대떡, 마약김밥, 육회까지 줄 서서 먹을 가치가 충분해요. 평일 낮에 가면 주말보다 덜 붐벼서 여유롭게 즐길 수 있습니다. 현금을 챙겨 가면 결제가 더 수월해요.',_binary '\0',73,'광장시장 먹거리 추천',0,39),(83,'2026-06-25 16:31:52.762556','2026-06-25 16:31:52.770462','RESTAURANT','갓 만든 순두부에 간장을 살짝 올려 먹으면 고소함이 입안 가득 퍼져요. 인기 있는 집은 아침 일찍 가야 자리가 있으니 서두르는 게 좋습니다.',_binary '\0',55,'강릉 초당두부 맛집',0,41),(84,'2026-06-25 16:31:52.790303','2026-06-25 16:31:52.800560','RESTAURANT','간장게장 백반 한 상이면 밥 두 공기는 기본으로 비우게 돼요. 짭조름한 게장에 돌산갓김치를 곁들이면 그야말로 밥도둑입니다. 예약하고 가면 대기 없이 먹을 수 있어요.',_binary '\0',62,'여수 게장 맛집 추천',0,42);
