INSERT INTO `recommendations` VALUES (1,'2026-06-22 11:55:30.341236','2026-06-22 11:56:03.465132',NULL,NULL,14316,'gpt-4o-mini','dc26eb8ccd454a9b6afaa5329c689aba3382f23681b178de68be922bc9517952','{\"budget\": 500000, \"themes\": [\"food\", \"mountain\", \"sea\"], \"endDate\": \"2026-07-18\", \"areaCode\": \"31\", \"startDate\": \"2026-07-15\", \"companions\": \"COUPLE\"}','{\"days\": [{\"dayNo\": 1, \"places\": [{\"title\": \"전통손두부닭갈비\", \"reason\": \"가평의 전통 음식인 손두부와 닭갈비를 맛볼 수 있는 곳으로, 맛집 탐방에 적합합니다.\", \"contentId\": \"1195574\", \"visitTime\": \"11:30\"}, {\"title\": \"강마루\", \"reason\": \"청평호반의 아름다운 경치를 즐기며 맛있는 닭갈비와 막국수를 맛볼 수 있습니다.\", \"contentId\": \"1208943\", \"visitTime\": \"13:30\"}, {\"title\": \"안동닭갈비막국수\", \"reason\": \"가평 지역의 특색 있는 음식인 닭갈비와 막국수를 제공하여 미식 경험을 쌓을 수 있습니다.\", \"contentId\": \"1195361\", \"visitTime\": \"15:30\"}], \"summary\": \"첫날은 가평 지역의 맛집 탐방을 하며 현지 음식을 즐겼습니다.\"}, {\"dayNo\": 2, \"places\": [{\"title\": \"여주 서화마을\", \"reason\": \"여주 서화마을은 아름다운 자연경관과 함께 전통 문화 체험이 가능한 곳입니다.\", \"contentId\": \"1008953\", \"visitTime\": \"10:00\"}, {\"title\": \"여주 양화나루\", \"reason\": \"양화나루에서 한적한 자연 속에서 산책하며 여유로운 시간을 보낼 수 있습니다.\", \"contentId\": \"1179635\", \"visitTime\": \"12:00\"}, {\"title\": \"여주 이포나루\", \"reason\": \"이포나루의 자연환경을 즐기며 더욱 깊이 있는 자연 탐방이 가능합니다.\", \"contentId\": \"1179681\", \"visitTime\": \"14:00\"}], \"summary\": \"둘째 날은 자연을 만끽하며 여유로운 시간을 보냈습니다.\"}, {\"dayNo\": 3, \"places\": [{\"title\": \"연무대(동장대)\", \"reason\": \"연무대에서 역사적인 장소를 방문하며 아름다운 경치를 감상할 수 있습니다.\", \"contentId\": \"1064469\", \"visitTime\": \"09:30\"}, {\"title\": \"스파라스파 (곤지암리조트)\", \"reason\": \"곤지암리조트에서 스파를 즐기며 휴식을 취할 수 있는 좋은 기회입니다.\", \"contentId\": \"1178650\", \"visitTime\": \"12:00\"}, {\"title\": \"분당 정자동 카페거리\", \"reason\": \"분당 정자동 카페거리에서 다양한 카페를 탐방하며 커플의 데이트 코스로 적합합니다.\", \"contentId\": \"1053768\", \"visitTime\": \"15:30\"}], \"summary\": \"셋째 날은 역사 탐방과 스파, 그리고 카페 데이트로 즐거운 시간을 보냈습니다.\"}, {\"dayNo\": 4, \"places\": [{\"title\": \"조무락계곡\", \"reason\": \"가평의 조무락계곡은 자연 속에서의 힐링을 제공하며 물놀이와 산책을 즐길 수 있습니다.\", \"contentId\": \"1059024\", \"visitTime\": \"10:00\"}, {\"title\": \"할머니손두부\", \"reason\": \"가평의 손두부 전문점에서 마지막 식사를 하며 여행을 마무리할 수 있습니다.\", \"contentId\": \"1203580\", \"visitTime\": \"13:00\"}], \"summary\": \"마지막 날은 자연을 즐기고 맛있는 음식으로 여행을 마무리했습니다.\"}], \"totalSummary\": \"4일 동안 바다와 해변, 맛집 탐방, 자연을 즐기며 커플의 힐링 여행을 다녀왔습니다.\"}',1,'SUCCESS',3),(2,'2026-06-22 14:41:48.180681','2026-06-22 14:42:16.202035',NULL,NULL,22002,'gpt-4o-mini','5fe4f8828d6671aed8245b3168ae3667d4fcf4018c3cf4191fbee0f534f0ee0e','{\"budget\": 300000, \"themes\": [\"food\", \"sea\"], \"endDate\": \"2026-07-10\", \"areaCode\": \"35\", \"startDate\": \"2026-07-08\", \"companions\": \"COUPLE\"}','{\"days\": [{\"dayNo\": 1, \"places\": [{\"title\": \"버드나무백숙\", \"reason\": \"첫날 저녁에 맛있는 백숙을 즐기며 여행의 시작을 알리기 위해 선택했습니다.\", \"contentId\": \"1014890\", \"visitTime\": \"18:00\"}, {\"title\": \"매학정일원\", \"reason\": \"자연경관과 함께 바다와 해변의 느낌을 느낄 수 있는 장소로, 저녁 산책에 적합합니다.\", \"contentId\": \"1129226\", \"visitTime\": \"19:30\"}], \"summary\": \"첫날 저녁은 맛집인 버드나무백숙에서 백숙을 즐기고, 매학정일원에서 저녁 산책을 하며 자연을 만끽했습니다.\"}, {\"dayNo\": 2, \"places\": [{\"title\": \"금오산성\", \"reason\": \"아침 산책으로 바다와 해변을 느낄 수 있는 경치 좋은 장소입니다.\", \"contentId\": \"1118806\", \"visitTime\": \"09:00\"}, {\"title\": \"안동 장승공원\", \"reason\": \"전통적인 한국 문화를 느낄 수 있는 장소로, 커플이 함께 걷기에 좋은 곳입니다.\", \"contentId\": \"1181011\", \"visitTime\": \"11:00\"}, {\"title\": \"봉화한약우프라자\", \"reason\": \"점심으로 지역 특산물을 맛볼 수 있는 곳으로, 미식 여행의 일환입니다.\", \"contentId\": \"1019843\", \"visitTime\": \"12:30\"}, {\"title\": \"순흥전통묵집\", \"reason\": \"전통 묵을 맛볼 수 있는 식당으로, 간단한 간식으로 적합합니다.\", \"contentId\": \"133007\", \"visitTime\": \"15:00\"}, {\"title\": \"안동 하회마을 겸암정사\", \"reason\": \"전통 문화와 바다의 느낌을 동시에 느낄 수 있는 관광지입니다.\", \"contentId\": \"1180879\", \"visitTime\": \"16:30\"}], \"summary\": \"둘째 날은 금오산성에서 자연을 즐기고, 안동 장승공원에서 전통문화를 느끼며, 봉화한약우프라자에서 점심을 먹은 후, 순흥전통묵집에서 간식으로 마무리했습니다.\"}, {\"dayNo\": 3, \"places\": [{\"title\": \"팔공산국립공원(갓바위지구)\", \"reason\": \"아침에 바다와 해변을 느낄 수 있는 트레킹을 즐기기에 적합한 장소입니다.\", \"contentId\": \"126019\", \"visitTime\": \"09:00\"}, {\"title\": \"약수식당\", \"reason\": \"점심으로 지역의 맛을 느낄 수 있는 식당입니다.\", \"contentId\": \"133518\", \"visitTime\": \"12:30\"}, {\"title\": \"구미 선산향교\", \"reason\": \"전통적인 분위기를 느끼며 커플이 함께 걷기에 좋은 장소입니다.\", \"contentId\": \"1119550\", \"visitTime\": \"14:00\"}], \"summary\": \"마지막 날은 팔공산국립공원에서 트레킹을 즐기고, 약수식당에서 점심을 먹은 후 구미 선산향교에서 전통적인 분위기를 만끽했습니다.\"}], \"totalSummary\": \"3일 동안 바다와 해변 테마에 맞춘 여행을 통해 맛집 투어와 전통 문화 체험을 즐겼습니다.\"}',3,'SUCCESS',3),(3,'2026-06-22 14:43:59.651584','2026-06-22 14:44:33.814703',NULL,NULL,17590,'gpt-4o-mini','413df74a5e95c4a314850d3f1a71f65525d04da76ac8a74e7dcc1eb8ac3819aa','{\"budget\": 300000, \"themes\": [\"food\", \"sea\"], \"endDate\": \"2026-07-01\", \"areaCode\": \"39\", \"startDate\": \"2026-06-29\", \"companions\": \"COUPLE\"}','{\"days\": [{\"dayNo\": 1, \"places\": [{\"title\": \"성산일출봉 [유네스코 세계자연유산]\", \"reason\": \"성산일출봉은 아름다운 바다 풍경을 감상할 수 있어 커플 여행에 적합합니다.\", \"contentId\": \"126436\", \"visitTime\": \"09:00\"}, {\"title\": \"안덕계곡\", \"reason\": \"안덕계곡은 조용한 자연 속에서 피크닉을 즐기기 좋은 장소입니다.\", \"contentId\": \"126440\", \"visitTime\": \"11:30\"}, {\"title\": \"돔베돈\", \"reason\": \"돔베돈은 제주 흑돼지를 맛볼 수 있는 유명한 맛집으로 미식 투어에 적합합니다.\", \"contentId\": \"135919\", \"visitTime\": \"13:00\"}, {\"title\": \"화순금모래해수욕장\", \"reason\": \"화순금모래해수욕장은 아름다운 해변에서 여유로운 시간을 보낼 수 있습니다.\", \"contentId\": \"126443\", \"visitTime\": \"15:00\"}], \"summary\": \"첫날은 성산일출봉과 안덕계곡에서 자연을 만끽하고, 유명한 맛집에서 제주 음식을 즐긴 후 해수욕장에서 여유로운 시간을 보냈습니다.\"}, {\"dayNo\": 2, \"places\": [{\"title\": \"천지연폭포\", \"reason\": \"천지연폭포는 수려한 경관을 자랑하며, 연인과 함께 걷기 좋은 장소입니다.\", \"contentId\": \"126438\", \"visitTime\": \"09:00\"}, {\"title\": \"하영 흑돼지구이집\", \"reason\": \"하영 흑돼지구이집에서 제주 특산물인 흑돼지를 맛볼 수 있습니다.\", \"contentId\": \"1018723\", \"visitTime\": \"12:00\"}, {\"title\": \"제주국제평화센터\", \"reason\": \"제주국제평화센터에서 제주도의 역사와 문화를 배울 수 있습니다.\", \"contentId\": \"130872\", \"visitTime\": \"14:00\"}, {\"title\": \"정방폭포\", \"reason\": \"정방폭포는 