INSERT INTO `travel_stories` VALUES (17,'2026-06-25 16:31:51.824397','2026-06-25 16:31:51.824397','성산일출봉 일출이 최고였고, 협재 바다도 잊지 못할 거예요!','오랜만의 여행이라 설렘 반 걱정 반이었어요.','https://tong.visitkorea.or.kr/cms/resource/08/2871008_image2_1.JPG',19,5,'제주 힐링 다녀온 후기',37),(18,'2026-06-25 16:31:51.828231','2026-06-25 16:31:51.828231','경복궁 야경과 N서울타워 전망이 완벽했습니다.','고궁 투어는 처음이라 기대됐어요.',NULL,18,4,'고궁 데이트 기록',39),(19,'2026-06-25 16:31:51.829700','2026-06-25 16:31:51.829700','해운대 야경에 힐링하고 왔습니다.','혼자 훌쩍 떠난 부산이었어요.','https://tong.visitkorea.or.kr/cms/resource/41/2655741_image2_1.jpg',20,5,'부산 바다 혼행 기록',38),(20,'2026-06-25 16:31:51.831005','2026-06-25 16:31:51.831005','광장시장 빈대떡이 최고였어요!','먹으러 떠난 여행이었죠.',NULL,NULL,4,'전국 맛집 탐방기',40);
