INSERT INTO `trip_places` VALUES (17,'성산일출봉은 바다와 해변의 멋진 경관을 감상할 수 있는 명소입니다.',1,'09:00:00.000000',25,5),(18,'점심으로 성산해촌에서 신선한 해산물을 맛볼 수 있습니다.',2,'12:00:00.000000',42,5),(19,'천지연폭포는 자연의 아름다움을 느낄 수 있는 장소입니다.',3,'14:00:00.000000',29,5),(20,'저녁으로 하영 흑돼지구이집에서 제주 특산물을 즐길 수 있습니다.',4,'18:00:00.000000',30,5),(21,'화순금모래해수욕장에서 해변에서의 여유로운 시간을 보낼 수 있습니다.',1,'09:00:00.000000',28,6),(22,'점심으로 소라횟집에서 신선한 회를 즐길 수 있습니다.',2,'12:00:00.000000',34,6),(23,'제주도 국가지질공원에서 자연을 탐험하며 아름다운 경관을 즐길 수 있습니다.',3,'14:00:00.000000',44,6),(24,'저녁으로 제주민속촌에서 전통 음식을 경험할 수 있습니다.',4,'18:00:00.000000',43,6),(29,'국립 용대자연휴양림에서 가족과 함께 자연 속에서 휴식을 취하며 다양한 체험을 할 수 있습니다.',1,'09:00:00.000000',54,8),(30,'한림대학교박물관에서 가족과 함께 다양한 전시를 관람하며 교육적인 시간을 보낼 수 있습니다.',2,'12:00:00.000000',55,8),(31,'양구의 석장골오골계숯불구이에서 가족과 함께 맛있는 식사를 하며 하루를 마무리할 수 있습니다.',3,'14:30:00.000000',56,8),(37,'가족이 함께 즐길 수 있는 강릉감자옹심에서 식사를 하며 휴식을 취할 수 있습니다.',3,'14:30:00.000000',53,7),(38,'광안리해수욕장에서 바다를 즐기기 위해.',1,'10:00:00.000000',57,9),(39,'해운대 근처에서 맛있는 한정식을 즐기기 위해.',2,'12:30:00.000000',58,9),(40,'해운대 관광특구에서 다양한 액티비티 체험을 위해.',3,'14:00:00.000000',59,9),(41,'자갈치 해안가에서 신선한 해산물을 맛보기 위해.',4,'17:30:00.000000',60,9),(42,'광복로패션거리를 둘러보며 쇼핑하고 저녁을 즐기기 위해.',5,'19:00:00.000000',61,9),(43,'부산 송도해수욕장에서 해양 스포츠를 즐기기 위해.',1,'10:00:00.000000',62,10),(44,'해변 근처에서 해산물 횟집에서 점심을 먹기 위해.',2,'12:30:00.000000',63,10),(45,'민주공원에서 산책하며 여유로운 시간을 보내기 위해.',3,'14:00:00.000000',64,10),(46,'스포원파크에서 재난안전체험을 통해 액티비티를 즐기기 위해.',4,'16:00:00.000000',65,10),(47,'친구들과 함께 맛있는 음식을 즐기기 위해.',5,'18:30:00.000000',66,10),(48,'역사적인 건물로, 문화적 가치가 높아 커플 여행에 적합합니다.',1,'10:00:00.000000',67,11),(49,'문화적인 공연과 예술작품을 즐길 수 있는 장소입니다.',2,'12:30:00.000000',68,11),(50,'전통찻집에서 한국의 차 문화를 경험할 수 있습니다.',3,'14:30:00.000000',69,11),(51,'서울의 역사와 문화를 배울 수 있는 공원입니다.',4,'16:00:00.000000',70,11),(52,'전통 한식을 제공하는 맛집으로, 저녁 식사에 적합합니다.',5,'18:30:00.000000',71,11),(53,'전통적인 분위기의 찻집에서 여유로운 아침을 즐길 수 있습니다.',1,'10:00:00.000000',72,12),(54,'다양한 체험을 통해 즐거운 시간을 보낼 수 있는 곳입니다.',2,'12:00:00.000000',73,12),(55,'역사와 문화를 동시에 배울 수 있는 거리입니다.',3,'14:30:00.000